import 'package:flutter/foundation.dart' show kIsWeb;
import 'package:flutter/material.dart';
import 'package:webview_flutter/webview_flutter.dart';
import 'package:url_launcher/url_launcher.dart';

/// Checkout screen that presents the Xendit payment portal.
/// Displays an in-app WebView on mobile platforms (Android/iOS)
/// and launches the checkout session in an external browser tab when run on the Web.
class XenditWebViewScreen extends StatefulWidget {
  /// The payment gateway URL generated by Xendit's Invoice API
  final String invoiceUrl;

  const XenditWebViewScreen({
    super.key,
    required this.invoiceUrl,
  });

  @override
  State<XenditWebViewScreen> createState() => _XenditWebViewScreenState();
}

class _XenditWebViewScreenState extends State<XenditWebViewScreen> {
  /// Controller managing the embedded mobile WebView lifecycle
  WebViewController? _controller;

  /// Loading indicator state while the web checkout page is fetching
  bool _isLoadingPage = true;

  @override
  void initState() {
    super.initState();

    if (kIsWeb) {
      // If testing on Chrome Web, open Xendit in a new tab so it doesn't crash or hit iframe restrictions
      _launchInBrowser();
    } else {
      // If running on Android APK / iOS, use the embedded in-app WebView
      _controller = WebViewController()
        ..setJavaScriptMode(JavaScriptMode.unrestricted)
        ..setNavigationDelegate(
          NavigationDelegate(
            onPageStarted: (_) => setState(() => _isLoadingPage = true),
            onPageFinished: (_) => setState(() => _isLoadingPage = false),
          ),
        )
        ..loadRequest(Uri.parse(widget.invoiceUrl));
    }
  }

  /// Opens the Xendit payment link in an external browser app
  Future<void> _launchInBrowser() async {
    final Uri uri = Uri.parse(widget.invoiceUrl);
    await launchUrl(uri, mode: LaunchMode.externalApplication);
    if (mounted) {
      setState(() => _isLoadingPage = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Xendit Checkout'),
        actions: [
          // User taps "Done" after completing payment simulation on Xendit to return to the app
          TextButton.icon(
            onPressed: () => Navigator.pop(context),
            icon: const Icon(Icons.check),
            label: const Text('Done'),
          ),
        ],
      ),
      body: kIsWeb
          ? Center(
              child: Padding(
                padding: const EdgeInsets.all(24.0),
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    const Icon(Icons.open_in_browser, size: 64, color: Colors.indigo),
                    const SizedBox(height: 16),
                    const Text(
                      'Xendit Checkout opened in a new browser tab.',
                      textAlign: TextAlign.center,
                      style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold),
                    ),
                    const SizedBox(height: 8),
                    const Text(
                      'After simulating your payment on Xendit, click "Done" in the top right corner to verify your order.',
                      textAlign: TextAlign.center,
                    ),
                    const SizedBox(height: 24),
                    OutlinedButton.icon(
                      onPressed: _launchInBrowser,
                      icon: const Icon(Icons.refresh),
                      label: const Text('Re-open Xendit Tab'),
                    ),
                  ],
                ),
              ),
            )
          : Stack(
              children: [
                if (_controller != null) WebViewWidget(controller: _controller!),
                if (_isLoadingPage)
                  const Center(child: CircularProgressIndicator()),
              ],
            ),
    );
  }
}